using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;

namespace TextureFlow.UnityEditor
{
 [Serializable] public class FlowTarget {
  public string key,label,globalId,materialGuid,texturePath; public int instanceId,slot,materialInstanceId;
 }
 [Serializable] public class FlowSnapshot {
  public int protocolVersion=1;public string sessionId,generatedUtc,message;public bool busy;public FlowTarget[] targets;
 }
 [Serializable] public class FlowCommand {
  public int protocolVersion=1;public string requestId,sessionId,action,materialPath,receiptPath;public string expiresUtc=DateTime.UtcNow.AddMinutes(1).ToString("O");public FlowTarget target;
 }
 [Serializable] public class FlowReply {
  public bool success;public string message,receiptPath;public bool applied;
 }
 [Serializable] public class FlowReceipt {
  public int protocolVersion=1;public string sessionId,originalGuid,backupPath,appliedGuid;public bool originalWasNull;public FlowTarget target;
 }
 [InitializeOnLoad] public static class FlowBridge {
  public const string Root="Library/TextureFlow";static double next;static bool running;
  public static string Session {get{string id=SessionState.GetString("TextureFlow.BridgeSession","");if(string.IsNullOrEmpty(id)){id=Guid.NewGuid().ToString("N");SessionState.SetString("TextureFlow.BridgeSession",id);}return id;}}
  static FlowBridge(){EditorApplication.update+=Tick;}
  static void Tick(){if(running||EditorApplication.timeSinceStartup<next)return;next=EditorApplication.timeSinceStartup+2;try{running=true;Publish();if(EditorApplication.isCompiling||EditorApplication.isUpdating)return;string requests=Root+"/requests";if(!Directory.Exists(requests))return;foreach(string path in Directory.GetFiles(requests,"*.json").OrderBy(File.GetLastWriteTimeUtc)){string result=Root+"/results/"+Path.GetFileName(path);if(File.Exists(result))continue;FlowReply reply;try{var command=JsonUtility.FromJson<FlowCommand>(File.ReadAllText(path));if(command==null||command.requestId!=Path.GetFileNameWithoutExtension(path))throw new Exception("Invalid request identifier.");reply=Execute(command);}catch(Exception ex){reply=new FlowReply{success=false,message=ex.Message};}Directory.CreateDirectory(Root+"/results");WriteJson(result,reply);}Publish();}catch(Exception ex){Debug.LogWarning("Texture Flow connector: "+ex.Message);}finally{running=false;}}
  public static void WriteJson(string path,object value){Directory.CreateDirectory(Path.GetDirectoryName(path));string temp=path+".tmp";File.WriteAllText(temp,JsonUtility.ToJson(value,true));if(File.Exists(path))File.Delete(path);File.Move(temp,path);}
  static string Hierarchy(Transform t){var names=new List<string>();while(t!=null){names.Add(t.name);t=t.parent;}names.Reverse();return string.Join(" / ",names.ToArray());}
  static string GuidFor(UnityEngine.Object o){return o==null?"":AssetDatabase.AssetPathToGUID(AssetDatabase.GetAssetPath(o));}
  public static FlowSnapshot Snapshot(){var targets=new List<FlowTarget>();bool busy=EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode;
   if(!busy)for(int sceneIndex=0;sceneIndex<SceneManager.sceneCount;sceneIndex++){var scene=SceneManager.GetSceneAt(sceneIndex);if(!scene.isLoaded||EditorSceneManager.IsPreviewScene(scene))continue;foreach(var root in scene.GetRootGameObjects())foreach(var renderer in root.GetComponentsInChildren<Renderer>(true)){if(!(renderer is SkinnedMeshRenderer)&&!(renderer is MeshRenderer))continue;var materials=renderer.sharedMaterials;string globalId=GlobalObjectId.GetGlobalObjectIdSlow(renderer).ToString();for(int slot=0;slot<materials.Length;slot++){var m=materials[slot];string texture="";if(m!=null&&m.HasProperty("_MainTex"))texture=AssetDatabase.GetAssetPath(m.GetTexture("_MainTex"));targets.Add(new FlowTarget{key=renderer.GetInstanceID()+":"+slot,instanceId=renderer.GetInstanceID(),slot=slot,globalId=globalId,materialGuid=GuidFor(m),materialInstanceId=m==null?0:m.GetInstanceID(),texturePath=texture,label=Hierarchy(renderer.transform)+" | "+(m==null?"Empty material":m.name)+" (slot "+slot+")"});}}}
   return new FlowSnapshot{sessionId=Session,generatedUtc=DateTime.UtcNow.ToString("O"),busy=busy,message=busy?"Unity is compiling, importing, or in Play mode. Wait and leave Play mode to apply.":targets.Count==0?"Open your avatar's scene in Unity to see its parts.":"Connected to Unity. Choose the avatar part to change.",targets=targets.OrderBy(t=>t.label,StringComparer.OrdinalIgnoreCase).ToArray()};}
  public static void Publish(){WriteJson(Root+"/connection.json",Snapshot());}
  static string ExportPath(string value){if(string.IsNullOrEmpty(value))throw new Exception("Missing export path.");string full=Path.GetFullPath(value);string allowed=Path.GetFullPath("Assets/TextureFlow/Exports")+Path.DirectorySeparatorChar;if(!full.StartsWith(allowed,StringComparison.OrdinalIgnoreCase))throw new Exception("Only Texture Flow exports can be applied.");return value.Replace('\\','/');}
  static Renderer RendererFor(FlowTarget t,string session){Renderer r=null;if(session==Session)r=EditorUtility.InstanceIDToObject(t.instanceId) as Renderer;else if(GlobalObjectId.TryParse(t.globalId,out var id))r=GlobalObjectId.GlobalObjectIdentifierToObjectSlow(id) as Renderer;if(r==null||!r.gameObject.scene.IsValid()||!r.gameObject.scene.isLoaded||EditorSceneManager.IsPreviewScene(r.gameObject.scene))throw new Exception("That avatar part is no longer open. Refresh the avatar parts and choose it again.");return r;}
  static void Assign(Renderer r,int slot,Material material){Undo.RecordObject(r,"Texture Flow material change");var mats=r.sharedMaterials;mats[slot]=material;r.sharedMaterials=mats;PrefabUtility.RecordPrefabInstancePropertyModifications(r);EditorUtility.SetDirty(r);EditorSceneManager.MarkSceneDirty(r.gameObject.scene);Undo.FlushUndoRecordObjects();SceneView.RepaintAll();}
  public static FlowReply Execute(FlowCommand c){if(c!=null&&(!DateTime.TryParse(c.expiresUtc,null,System.Globalization.DateTimeStyles.RoundtripKind,out var expiry)||expiry.ToUniversalTime()<DateTime.UtcNow))throw new Exception("This request expired. Return to Texture Flow and try again.");if(c==null||c.protocolVersion!=1||c.sessionId!=Session)throw new Exception("Unity reconnected. Refresh avatar parts and try again.");if(EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling||EditorApplication.isUpdating)throw new Exception("Leave Play mode and wait for Unity to finish importing before applying.");if(c.action=="restore")return Restore(c);if(c.action!="apply"||c.target==null)throw new Exception("Unsupported connector action.");var r=RendererFor(c.target,c.sessionId);var mats=r.sharedMaterials;if(c.target.slot<0||c.target.slot>=mats.Length)throw new Exception("Material slots changed. Refresh avatar parts.");if(GlobalObjectId.GetGlobalObjectIdSlow(r).ToString()!=c.target.globalId)throw new Exception("The avatar part changed. Refresh and select it again.");
   if(!Guid.TryParse(c.requestId,out var requestGuid))throw new Exception("Invalid request identifier.");
   string replayPath=Path.GetDirectoryName(ExportPath(c.materialPath)).Replace('\\','/')+"/apply-backup-"+c.requestId+".json";
   if(File.Exists(replayPath)){var prior=JsonUtility.FromJson<FlowReceipt>(File.ReadAllText(replayPath));if(prior!=null&&prior.target.instanceId==r.GetInstanceID()&&prior.target.slot==c.target.slot&&GuidFor(mats[c.target.slot])==prior.appliedGuid)return new FlowReply{success=true,applied=true,receiptPath=replayPath,message="This effect is already applied. Restore previous material is available."};throw new Exception("This request was already processed. Refresh before making a new change.");}
   var previous=mats[c.target.slot];if((previous==null?0:previous.GetInstanceID())!=c.target.materialInstanceId||GuidFor(previous)!=(c.target.materialGuid??""))throw new Exception("This material changed since it was selected. Refresh avatar parts before applying.");string materialPath=ExportPath(c.materialPath);if(Path.GetFileName(materialPath)!="Animated.mat")throw new Exception("Choose the generated Animated.mat material.");var generated=AssetDatabase.LoadAssetAtPath<Material>(materialPath);if(generated==null||generated.shader==null||generated.shader.name!="TextureFlow/Masked Scroll")throw new Exception("The animated material is not ready. Wait for Unity to finish importing.");
   string directory=Path.GetDirectoryName(materialPath).Replace('\\','/');string receiptPath=directory+"/apply-backup-"+c.requestId+".json";string backupPath=directory+"/PreviousMaterial-"+c.requestId+".mat";if(previous!=null){var backup=new Material(previous);AssetDatabase.CreateAsset(backup,backupPath);}
   var receipt=new FlowReceipt{sessionId=Session,target=c.target,originalGuid=GuidFor(previous),originalWasNull=previous==null,backupPath=previous==null?"":backupPath,appliedGuid=GuidFor(generated)};WriteJson(receiptPath,receipt);AssetDatabase.SaveAssets();Assign(r,c.target.slot,generated);return new FlowReply{success=true,applied=true,receiptPath=receiptPath,message="Applied to "+c.target.label+". Save the scene in Unity to keep this change. Restore previous material is available."};
  }
  static FlowReply Restore(FlowCommand c){string path=ExportPath(c.receiptPath);if(!Path.GetFileName(path).StartsWith("apply-backup-",StringComparison.Ordinal)||Path.GetExtension(path)!=".json")throw new Exception("Invalid restore record.");var receipt=JsonUtility.FromJson<FlowReceipt>(File.ReadAllText(path));if(receipt==null||receipt.protocolVersion!=1||receipt.target==null)throw new Exception("Missing restore information.");var r=RendererFor(receipt.target,receipt.sessionId);var mats=r.sharedMaterials;if(receipt.target.slot<0||receipt.target.slot>=mats.Length||GuidFor(mats[receipt.target.slot])!=receipt.appliedGuid)throw new Exception("This slot was changed after applying. Restore was stopped to preserve the newer assignment.");Material previous=null;if(!receipt.originalWasNull){if(!string.IsNullOrEmpty(receipt.originalGuid))previous=AssetDatabase.LoadAssetAtPath<Material>(AssetDatabase.GUIDToAssetPath(receipt.originalGuid));if(previous==null&&!string.IsNullOrEmpty(receipt.backupPath))previous=AssetDatabase.LoadAssetAtPath<Material>(ExportPath(receipt.backupPath));if(previous==null)throw new Exception("The previous material and its backup are unavailable.");}Assign(r,receipt.target.slot,previous);return new FlowReply{success=true,applied=false,message="Previous material restored. Save the scene in Unity to keep this change."};}
 }
}
